import * as React from "react";
import { fireEvent, render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import ConsoleSpy from "../../lib/tests/ConsoleSpy";
import * as stories from "./SearchInput.stories";
import SearchInput from "./SearchInput";

const { Basic } = composeStories(stories) as any;

describe("SearchInput component", () => {
  let consoleSpy = ConsoleSpy();

  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("passes through props", () => {
    render(<SearchInput data-testid="searchinput" />);
    expect(screen.getByTestId("searchinput")).toBeTruthy();
  });

  it("display warnings with invalid props", () => {
    render(<SearchInput data-testid="searchinput" debounce={-100} />);
    expect(consoleSpy.warn).toHaveBeenCalledTimes(1);
    expect(consoleSpy.warn.mock.calls[0][0]).toMatch(
      / expects the `debounce` prop to be greater than zero/
    );
  });

  it("dispatch value on enter key", async () => {
    const onChange = jest.fn();
    const onSearch = jest.fn();
    render(<SearchInput onChange={onChange} onSearch={onSearch} />);

    const input = screen.getByRole("textbox");
    await userEvent.type(input, "test{enter}");
    expect(input).toHaveValue("test");
    expect(onChange).toHaveBeenCalledTimes(4);
    expect(onSearch).toHaveBeenCalledTimes(1);
    expect(onSearch).toHaveBeenLastCalledWith("test");
  });

  it("Reset value on click on clear button", async () => {
    const onChange = jest.fn();
    const onSearch = jest.fn();
    render(<SearchInput onChange={onChange} onSearch={onSearch} />);

    const input = screen.getByRole("textbox");
    await userEvent.type(input, "test{enter}");
    expect(input).toHaveValue("test");
    expect(onChange).toHaveBeenCalledTimes(4);

    fireEvent.click(screen.getByRole("button", { name: /clear/ }));
    expect(input).toHaveValue("");
    expect(onChange).toHaveBeenCalledTimes(5);
    expect(onChange).toHaveBeenLastCalledWith(expect.anything(), "");
  });

  it("allow forwardRef", () => {
    const SearchInputWithRef = () => {
      const searchInputRef = React.useRef<HTMLInputElement>(null);
      React.useEffect(() => {
        searchInputRef.current && searchInputRef.current.focus();
      }, []);
      return <SearchInput inputRef={searchInputRef} />;
    };

    render(<SearchInputWithRef />);
    expect(screen.getByRole("textbox")).toHaveFocus();
  });

  it("allow to debounce onChange events", async () => {
    const onChange = jest.fn();
    render(<SearchInput onChange={onChange} debounce={500} />);

    const input = screen.getByRole("textbox");
    await userEvent.type(input, "test");
    expect(input).toHaveValue("test");

    // check that there is no immediate dispatch and only one deferred
    expect(onChange).toHaveBeenCalledTimes(0);
    await waitFor(() => expect(onChange).toHaveBeenCalledTimes(1));
  });
});
